schema:
{
  "description": "Chiamate del servizio clienti",
  "baseAnalyzerId": "prebuilt-audio",
  "config": {
    "locales": [
      "it-IT"
    ]
  },
  "fieldSchema": {
    "fields": {
      "NumeroPratica": {
        "type": "string",
        "method": "generate",
        "description": "Codice pratica pronunciato dal cliente, nel formato TK- seguito da sei cifre."
      },
      "Motivo": {
        "type": "string",
        "method": "classify",
        "enum": [
          "fatturazione",
          "guasto",
          "disdetta",
          "informazioni",
          "altro"
        ],
        "description": "Motivo principale della chiamata."
      },
      "Esito": {
        "type": "string",
        "method": "classify",
        "enum": [
          "risolto",
          "da richiamare",
          "escalation",
          "altro"
        ],
        "description": "Esito alla fine della chiamata."
      }
    }
  }
}
